#!/usr/bin/env bash
# ==============================================================================
# BepInEx Android - Prebuilt Verification & Alignment Check
#
# Verifies the native runtime artifacts and the managed framework archives against
# the SHA-256 manifest produced by CI, and checks 16KB ELF page alignment
# (required from Android 15 / API 35).
#
# The manifest is the trust anchor. It is generated by:
#   .github/workflows/build-native-deps.yml   (dobby, pine, NDK runtime libs)
#   .github/workflows/fetch-runtime.yml       (coreclr, PAL shims, dotnet.zip)
# and committed at launcher/provenance/sha256sums.txt. Nothing here may hard-code a
# checksum: a hand-maintained list silently rots the moment CI rebuilds.
# ==============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
REPO_DIR="$(cd "${ROOT_DIR}/.." && pwd)"

JNI_DIR="${ROOT_DIR}/app/src/main/jniLibs/arm64-v8a"
ASSETS_DIR="${ROOT_DIR}/app/src/main/assets"
MANIFEST="${REPO_DIR}/provenance/sha256sums.txt"

# --update-manifest regenerates the manifest from what is actually in the tree.
# It is the only way to change a recorded hash, and it is deliberately explicit:
# the manifest is the trust anchor, so a hash should change because a pinned
# input was deliberately bumped (see provenance/dotnet-runtime.env), never as a
# side effect of running a check. The verification that follows is still run, so
# a regenerated manifest is a *description* of the tree rather than a way past
# the checks.
UPDATE_MANIFEST=0
for arg in "$@"; do
    case "$arg" in
        --update-manifest) UPDATE_MANIFEST=1 ;;
        -*) echo "unknown option: $arg" >&2; exit 2 ;;
        *)  echo "unexpected argument: $arg" >&2; exit 2 ;;
    esac
done

# Regenerating rewrites the manifest, so comparing the old hashes first would
# report every changed file as a failure and end on RESULT: FAILED while having
# just written the new manifest. The comparison is meaningless in that mode; the
# post-write re-verification below is the check that counts.
FAILURES=0
ALIGN_FAILURES=0

echo "============================================================"
echo " BepInEx Android - Prebuilt Verification                    "
echo "============================================================"
echo "manifest: ${MANIFEST}"

if [ ! -f "${MANIFEST}" ]; then
    echo "[FATAL] Manifest not found: ${MANIFEST}"
    echo "        Generate it from CI (build-native-deps + fetch-runtime) or run:"
    echo "          scripts/verify_prebuilts.sh --update-manifest   # only from a trusted build"
    exit 1
fi

cd "${REPO_DIR}"

echo ""
echo "[1/3] Verifying SHA-256 against manifest..."
if [ "$UPDATE_MANIFEST" = 1 ]; then
    echo "  [--update-manifest] recording the tree as the new manifest:"
    while read -r expected path; do
        [ -n "${expected:-}" ] || continue
        case "$expected" in \#*) continue ;; esac
        if [ ! -f "${path}" ]; then
            echo "    [-REMOVED] ${path}"
            continue
        fi
        actual="$(sha256sum "${path}" | awk '{print $1}')"
        if [ "$actual" = "$expected" ]; then
            echo "    [same]    ${path}"
        else
            echo "    [CHANGED] ${path}"
            echo "                ${expected:0:16}... -> ${actual:0:16}..."
        fi
    done < "${MANIFEST}"
else
    while read -r expected path; do
        [ -n "${expected:-}" ] || continue
        case "$expected" in \#*) continue ;; esac
        if [ ! -f "${path}" ]; then
            echo "  [MISSING]  ${path}"
            FAILURES=$((FAILURES + 1))
            continue
        fi
        actual="$(sha256sum "${path}" | awk '{print $1}')"
        if [ "$actual" = "$expected" ]; then
            echo "  [OK]       ${path}"
        else
            echo "  [MISMATCH] ${path}"
            echo "             expected ${expected}"
            echo "             actual   ${actual}"
            FAILURES=$((FAILURES + 1))
        fi
    done < "${MANIFEST}"
fi

echo ""
echo "[2/3] Checking 16KB ELF page alignment (Android 15+ / API 35)..."
check_align() {
    local so="$1" label="$2"
    local bad_align=""
    while read -r align; do
        [ -n "${align}" ] || continue
        # shellcheck disable=SC2059
        if [ "$((align))" -lt 16384 ]; then
            bad_align="${bad_align}${align} "
        fi
    done < <(readelf -lW "${so}" 2>/dev/null | awk '$1 == "LOAD" { print $NF }')
    if [ -n "${bad_align}" ]; then
        echo "  [UNALIGNED] ${label} PT_LOAD p_align: ${bad_align}"
        ALIGN_FAILURES=$((ALIGN_FAILURES + 1))
    else
        echo "  [OK]        ${label}"
    fi
}

# Artifacts checked in from CI.
for so in "${JNI_DIR}"/*.so; do
    [ -f "${so}" ] || continue
    check_align "${so}" "$(basename "${so}")"
done

# libmain.so and libfusion.so are produced by the Gradle/CMake build, so they are
# only present here after a build. They are covered authoritatively by the
# `zipalign -c -P 16` check on the packaged APK; check them here too when we can.
for candidate in "${ROOT_DIR}/app/build/intermediates/merged_native_libs"/*/*/out/lib/arm64-v8a; do
    [ -d "${candidate}" ] || continue
    for so in "${candidate}/libmain.so" "${candidate}/libfusion.so"; do
        [ -f "${so}" ] || continue
        check_align "${so}" "$(basename "${so}") (cmake)"
    done
    break
done

echo ""
echo "[3/3] Cross-checking that no unlisted binary is shipped..."
UNLISTED=0

if [ "$UPDATE_MANIFEST" = 1 ]; then
    # Paths are emitted in the same order the old manifest used (jniLibs first,
    # then assets) so the diff of a regeneration reads as the change it is.
    {
        sed -n '1,8p' "${MANIFEST}" 2>/dev/null || true
        ( cd "${REPO_DIR}" && for so in "${JNI_DIR}"/*.so; do
              [ -f "${so}" ] || continue
              sha256sum "launcher/app/src/main/jniLibs/arm64-v8a/$(basename "${so}")"
          done )
        ( cd "${REPO_DIR}" && for asset in "${ASSETS_DIR}"/*.zip; do
              [ -f "${asset}" ] || continue
              sha256sum "launcher/app/src/main/assets/$(basename "${asset}")"
          done )
    } > "${MANIFEST}.new"
    mv "${MANIFEST}.new" "${MANIFEST}"
    echo "  [OK]        manifest regenerated: ${MANIFEST}"
    echo ""
    echo "  re-verifying against the regenerated manifest:"
    while read -r expected path; do
        [ -n "${expected:-}" ] || continue
        case "$expected" in \#*) continue ;; esac
        actual="$(sha256sum "${path}" 2>/dev/null | awk '{print $1}')"
        if [ "$actual" = "$expected" ]; then
            echo "    [OK]       ${path}"
        else
            echo "    [FAIL]     ${path}"
            FAILURES=$((FAILURES + 1))
        fi
    done < "${MANIFEST}"
fi

# Reported after a regeneration as well as a plain check: a regenerated manifest
# still has to account for everything in jniLibs.
for so in "${JNI_DIR}"/*.so; do
    [ -f "${so}" ] || continue
    rel="launcher/app/src/main/jniLibs/arm64-v8a/$(basename "${so}")"
    if ! grep -q " ${rel}\$" "${MANIFEST}"; then
        echo "  [UNLISTED]  ${rel}  (not covered by the manifest)"
        UNLISTED=$((UNLISTED + 1))
    fi
done

echo ""
echo "============================================================"
if [ "${FAILURES}" -ne 0 ] || [ "${ALIGN_FAILURES}" -ne 0 ] || [ "${UNLISTED}" -ne 0 ]; then
    echo " RESULT: FAILED"
    echo "   checksum mismatches/missing : ${FAILURES}"
    echo "   16KB alignment failures     : ${ALIGN_FAILURES}"
    echo "   unlisted shipped binaries   : ${UNLISTED}"
    echo "============================================================"
    exit 1
fi

echo " RESULT: PASSED - every shipped artifact matches the CI manifest."
echo "============================================================"